attempt.kernel_code:
pub fn attempt(st: &Prov, a: &Attempt) -> (Prov, AfterAttempt) {
    if !st.trying {
        return (*st, AfterAttempt { store: false, will_end: false });
    }
    if st.pending {
        return (Prov { status: Status::Connecting, trying: false, ..*st }, AfterAttempt { store: false, will_end: false });
    }
    if !a.parsed {
        return (Prov { status: Status::Invalid, trying: false, ..*st }, AfterAttempt { store: false, will_end: false });
    }
    if !a.driver_ok {
        return (Prov { status: Status::Invalid, trying: false, ..*st }, AfterAttempt { store: false, will_end: false });
    }
    if !a.connected {
        return (Prov { status: Status::Failed, trying: false, ..*st }, AfterAttempt { store: false, will_end: false });
    }
    (
        Prov { status: Status::Connected, has_ip: a.got_ip, trying: false, stored: true, ..*st },
        AfterAttempt { store: true, will_end: true },
    )
}

