pub fn http(st: &Prov, req: &Req) -> (Option<Prov>, Resp) {
    match req {
        Req::Panel => (None, Resp::Panel),
        Req::UpdatePanel => (None, Resp::UpdatePanel),
        Req::List => (None, Resp::List),
        Req::Status => {
            let connected = is_connected(st.status);
            let show_ip = if connected { st.has_ip } else { false };
            let resp = Resp::Status { status: st.status, show_ip };
            if connected {
                (Some(Prov { connected_seen: true, ..*st }), resp)
            } else {
                (None, resp)
            }
        }
        Req::Setup { fits } => {
            if st.stored {
                // A setup connected and was stored; provisioning ends.
                // (Upstream answers `.`, shows `connecting` and drops the
                // setup when the AP goes down: STATUS.md.)
                (None, Resp::SetupRefused)
            } else if *fits {
                (Some(Prov { status: Status::Connecting, pending: true, ..*st }), Resp::SetupTaken)
            } else {
                (None, Resp::SetupTooLarge)
            }
        }
        Req::OtherGet => (None, Resp::Redirect),
        Req::Other => (None, Resp::NotFound),
    }
}

