pub fn ota_end(write_ok: bool, complete: bool, verified: bool) -> OtaEnd {
    if !write_ok {
        OtaEnd::WriteFailed
    } else if !complete {
        OtaEnd::Incomplete
    } else if verified {
        OtaEnd::Reset
    } else {
        OtaEnd::VerifyFailed
    }
}

